    Source: packages/compose-gen/specs/organisms/hero-split.json
    A split hero: a badge, the heading, a lead, an extra under it and one or two actions, beside the media. Axes: extra (stats: three figures, avatars: faces and a proof line, minis: two small feature cards, quote: a quote over three figures, none), media (picture, card: a floating card on the picture, grid: four pictures with captions, plans: two plan cards on the picture), mediaSide, tone.
    Props (p): id, title, lead, badge, level, actions, content, extra, media, mediaSide, tone, landmarkLabel. -#}
{%- set v_id = og_def(p['id'], none) -%}
{%- set v_title = og_def(p['title'], none) -%}
{%- set v_lead = og_def(p['lead'], '') -%}
{%- set v_badge = og_def(p['badge'], '') -%}
{%- set v_level = og_def(p['level'], 1) -%}
{%- set v_actions = og_def(p['actions'], none) -%}
{%- set v_content = og_def(p['content'], none) -%}
{%- set v_extra = og_def(p['extra'], 'stats') -%}
{%- set v_media = og_def(p['media'], 'picture') -%}
{%- set v_mediaSide = og_def(p['mediaSide'], 'end') -%}
{%- set v_tone = og_def(p['tone'], 'default') -%}
{%- set v_landmarkLabel = og_def(p['landmarkLabel'], none) -%}
{%- set f_1 -%}
  {{ og_include('blocks/hero-split-media.html.j2', {'p': {'content': v_content, 'alt': v_title, 'media': v_media}}) }}
{%- endset -%}
{%- set c_2 -%}
  {{ og_include('blocks/hero-split-extras.html.j2', {'p': {'content': v_content, 'extra': v_extra}}) }}
  {{ og_include('blocks/action-group.html.j2', {'p': {'primary': og_get(v_actions, ['cta']), 'primaryHref': og_get(v_actions, ['href']), 'secondary': (og_get(v_actions, ['secondary']) if og_t(og_eq(og_get(v_actions, ['mode']), 'two')) else none), 'secondaryHref': og_get(v_actions, ['secondaryHref'])}}) }}
{%- endset -%}
